;; curriculum: Calc-1 (gr 12 / undergrad) — definite integral as accumulated area; prerequisites: gallery, deriv
;; math target: the shaded region under the curve grows as you move right; the integral piles up strips of area.

app riya-level-area "1.1.0"
"riya level 20 · Area — the shaded region grows as you run right; every vertical strip you pass adds its height to the total. Skate the curve and fill the area — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaAreaOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaAreaBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaAreaPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaAreaFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaAreaPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaAreaCurveSample = {
    x : number!
    y : number!
  }
  type RiyaAreaCurve = {
    label : string
    color : string
    samples : [RiyaAreaCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaAreaGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaAreaFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaAreaState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaAreaBody = { x: -9, y: 2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaAreaPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaAreaFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "area"
    platforms : [RiyaAreaPlatform] = []
    curves : [RiyaAreaCurve] = []
    guides : [RiyaAreaGuide] = []
    areaSamples : [RiyaAreaCurveSample] = []
  }

  entity AreaTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait AreaBody = Body.traits.PlatformerBody -> RiyaAreaState {
    events {
      STEER: AREA_STEER
      JUMP: AREA_LEAP
      PLACE: AREA_PLACE
      RESTART: AREA_RESTART
      BODY_MOVED: AREA_MOVED
      BODY_JUMPED: AREA_JUMPED
      BODY_LANDED: AREA_LANDED
      BODY_HAZARD: AREA_HAZARD
      BODY_GOAL: AREA_GOAL
      BODY_FELL: AREA_FELL
      BODY_SKATE_START: AREA_SKATE_ON
      BODY_SKATE_END: AREA_SKATE_OFF
      SET_PLATFORMS: AREA_SET_PLATFORMS
      SET_SKATE_CURVE: AREA_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -9, y: 2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait AreaGate = Gate.traits.ObjectiveFlow -> RiyaAreaState {
    events {
      PROGRESS: AREA_PROGRESS
      GAME_END: AREA_GAME_END
      RESTART: AREA_RESTART
    }
    config { running: true }
  }

  trait AreaFx = Particles.traits.FxParticles -> RiyaAreaState {
    events {
      BURST: AREA_BURST
    }
    config { running: true }
  }

  trait AreaTutorialPreview -> AreaTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait AreaTutorial = Tutorial.traits.TutorialOverlay -> AreaTutorialData {
    events {
      SHOW: AREA_TUTORIAL_SHOW
      TUTORIAL_DONE: AREA_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.AreaTutorialPreview
      steps: [
        { id: "intro", title: "Area", body: "Run right and watch the blue region grow. Each vertical strip you pass adds its height to the total area under the curve." }
      ]
    }
  }

  trait AreaPickup = Pickup.traits.Pickup -> RiyaAreaState {
    events {
      PICKED: AREA_PICKED
      COLLECT: AREA_COLLECT
      PICKUP_SET_COMPLETED: AREA_PICKUP_SET_COMPLETED
      SET_FEATURES: AREA_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait AreaLevelData -> @rebindable RiyaAreaState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "area"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          areaSamples: (array/map @config.areaSamples (fn a @a))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaAreaPlatform]!
        stars : [RiyaAreaPickup]!
        skateCurve : [RiyaAreaCurveSample]
        curveOverlay : [RiyaAreaCurve]
        guides : [RiyaAreaGuide]
        areaSamples : [RiyaAreaCurveSample]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Area"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = x/4 + 3"
