        @tier "domain"
      platforms : [RiyaAreaPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 2.8, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 3.2, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 3.6, type: "ground" }
