  trait RiyaAreaPlay -> @rebindable RiyaAreaState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit AREA_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "AREA_LEFT", KeyA: "AREA_LEFT", ArrowRight: "AREA_RIGHT", KeyD: "AREA_RIGHT", ArrowUp: "AREA_JUMP", KeyW: "AREA_JUMP", Space: "AREA_JUMP" }
            keyUpMap: { ArrowLeft: "AREA_STOP", KeyA: "AREA_STOP", ArrowRight: "AREA_STOP", KeyD: "AREA_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: [ { samples: (array/filter @entity.areaSamples (fn smp (<= (object/get @smp x) (+ @entity.body.x 0.3)))), baseline: -2, color: @config.regionColor, opacity: 0.25, label: "∫ so far" } ]
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "AREA_LEFT", right: "AREA_RIGHT", up: "AREA_JUMP" }, directionReleaseEvents: { left: "AREA_STOP", right: "AREA_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "area")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.areaSamples @payload.areaSamples)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit AREA_SET_PLATFORMS { platforms: @payload.platforms })
        (emit AREA_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit AREA_SET_FEATURES { features: @payload.stars })

      AREA_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit AREA_STEER { dir: -1 })

      AREA_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit AREA_STEER { dir: 1 })

      AREA_STOP -> idle when (== @entity.active true)
        (emit AREA_STEER { dir: 0 })

      AREA_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit AREA_LEAP {})

      AREA_FELL -> idle when (== @entity.active true)
        (emit AREA_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit AREA_BURST { particles: (array/map [ "fx-area-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      AREA_SKATE_ON -> idle when (== @entity.active true)
        (emit AREA_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "each strip adds area", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-area-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      AREA_PICKED -> idle when (== @entity.active true)
        (emit AREA_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (if (== @payload.kind "star") @payload.glyph @payload.message), ttl: 2 })) })
      AREA_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit AREA_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      AREA_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit AREA_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "the integral is the total shaded area", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit AREA_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      AREA_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "area" })

      AREA_TUTORIAL_DONE -> idle
        (emit AREA_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "the shaded region grows as you run right", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "AREA_LEFT", KeyA: "AREA_LEFT", ArrowRight: "AREA_RIGHT", KeyD: "AREA_RIGHT", ArrowUp: "AREA_JUMP", KeyW: "AREA_JUMP", Space: "AREA_JUMP" }
            keyUpMap: { ArrowLeft: "AREA_STOP", KeyA: "AREA_STOP", ArrowRight: "AREA_STOP", KeyD: "AREA_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: [ { samples: (array/filter @entity.areaSamples (fn smp (<= (object/get @smp x) (+ @entity.body.x 0.3)))), baseline: -2, color: @config.regionColor, opacity: 0.25, label: "∫ so far" } ]
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      AREA_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      AREA_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      AREA_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      AREA_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (AREA_LEAP), which accepts it only while grounded."
        @tier "domain"
      AREA_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      AREA_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      AREA_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      AREA_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      AREA_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the curve — fires the equation fx burst."
        @tier "domain"
      AREA_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the pickup glyph, the challenge trait applies kind-conditional effects."
        @tier "domain"
      AREA_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      AREA_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      AREA_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow/pickup authorities (renamed RESTART)."
        @tier "domain"
      AREA_BURST -> external {
        particles : [RiyaAreaFx]
      }
        @description "Particle batch spawned on star pickup, boost pickup or pit respawn; fx-particles fades it."
        @tier "domain"
      AREA_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the Play trait; the objective-flow gate resolves won from it."
        @tier "domain"
      AREA_GAME_END -> external {
