  trait AreaChallenge -> @rebindable RiyaAreaState [game-core, instance] {
    initial: idle

    state idle {
      AREA_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (== @payload.kind "strip")
          (emit AREA_BURST { particles: (array/concat
            { id: "narrative-strip", type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: "∫ₐᵇ f(x) dx", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            []
          ) })
          null)
    }

    emits {
      AREA_BURST -> external {
        particles : [RiyaAreaFx]
      }
        @description "Particle batch spawned on the strip-pad pickup's definite-integral narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      AREA_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "area"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaAreaClear -> @rebindable RiyaAreaState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "AREA_NEXT", variant: "primary" } ]
        })

      AREA_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      AREA_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-area"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Area clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "The region behind you filled strip by strip — that growing area is the integral."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-area" as RiyaAreaPage -> AreaLevelData, AreaBody, AreaGate, AreaFx, AreaPickup, AreaTutorial, RiyaAreaGenre, RiyaAreaPlay, AreaChallenge, RiyaAreaClear
}
